    add_node('Note ' + str(len([n for n in nodes.values() if n['type'] == 'n8n-nodes-base.stickyNote']) + 1), 'n8n-nodes-base.stickyNote', 1, {'content': content, 'height': hgt, 'width': wdt, 'color': color}, [x, y])
