            assert sorted(_facts['input0']) == sorted(_facts['preds']), 'R115: ' + _cb['join'] + "'s first input is not the callback builders: " + str(_facts)
            _cl = next(n['parameters']['jsCode'] for n in _w['nodes'] if n['name'] == _cb['ledger'])
